"]=167.0,["height"]=727.0,["border"]={0.0,0.0,0.0,0.0},["ppu"]=100.0},["/offline/spine-ui/7501003/-2374055018006405441.png"]={["name"]="4",["url"]="/offline/spine-ui/7501003/-2374055018006405441.png",["width"]=81.0,["height"]=570.0,["border"]={0.0,0.0,0.0,0.0},["ppu"]=100.0},["/offline/spine-ui/7501003/-931494651645720447.png"]={["name"]="1",["url"]="/offline/spine-ui/7501003/-931494651645720447.png",["width"]=102.0,["height"]=516.0,["border"]={0.0,0.0,0.0,0.0},["ppu"]=100.0},["/offline/spine-ui/7501003/-235448711314206687.png"]={["name"]="jindutiao",["url"]="/offline/spine-ui/7501003/-235448711314206687.png",["width"]=167.0,["height"]=727.0,["border"]={0.0,0.0,0.0,0.0},["ppu"]=100.0},["/offline/spine-ui/7501003/371821161552492523.png"]={["name"]="2",["url"]="/offline/spine-ui/7501003/371821161552492523.png",["width"]=49.0,["height"]=475.0,["border"]={0.0,0.0,0.0,0.0},["ppu"]=100.0}},["clips"]={},["version"]=6,["unsupported"]={}}
SOURCES={["75010_skin_VodkaMirror03_spine"]="-- 策划\r\nlocal winIndex = 10 -- 胜利动画,填下标\r\nlocal loseIndex = 12 -- 失败动画,填下标\r\nlocal clickIndex = 9 -- 点击动画,填下标\r\nlocal startNum = 20 -- 初始值 （100是满了）\r\nlocal holdTime = 0.1 -- 无动作多长时间（秒）会开始掉进度\r\nlocal downTime = 0.5 -- 降低百分1需要的秒数\r\nlocal addNum = 18 -- 每次点击增加多少 （100是满了）\r\n-- local showtime = 1000 -- 事件触发后多长时间显示UI,不能改，要特效改\r\nlocal hideTime = 0 -- 触发胜利失败动画多长时间后隐藏UI\r\nlocal lerpNum = 0.01 -- 每帧增加多少\r\n\r\n-- 程序\r\nlocal img_fill\r\nlocal CardLive2DItem\r\nlocal isOver = nil\r\nlocal timer = 0\r\nlocal slider_min = 0 ---170\r\nlocal slider_max = 1 -- 200\r\nlocal height = 0\r\nlocal _height = 0\r\nlocal len = 0\r\nlocal isUp = true\r\nlocal firstHeight = 0\r\nlocal isCan = false\r\n\r\nfunction Awake()\r\n    img_fill = ComUtil.GetCom(fill, \"Image\")\r\nend\r\n\r\nfunction Refresh(_CardLive2DItem)\r\n    CardLive2DItem = _CardLive2DItem\r\n    -- 初始化\r\n    len = slider_max - slider_min\r\n    _height = slider_min + startNum * (len / 100)\r\n    firstHeight = _height\r\n    height = slider_min\r\n    timer = holdTime\r\n    -- 显示ui\r\n    FuncUtil:Call(function()\r\n        CSAPI.SetGOActive(effect, true)\r\n        isOver = false\r\n    end, nil, 1000)\r\nend\r\n\r\nfunction Update()\r\n    if (isOver == nil) then\r\n        return\r\n    end\r\n    if (_height ~= height) then\r\n        SetSoftMaskHeight()\r\n    end\r\n    if (isOver) then\r\n        if (CardLive2DItem.IsIdle()) then\r\n            local index = winIndex\r\n            if (height <= slider_min) then -- 胜利\r\n                index = loseIndex\r\n            end\r\n            CardLive2DItem.PlayByIndex(index)\r\n            isOver = nil\r\n            -- 隐藏ui\r\n            FuncUtil:Call(function()\r\n                if (effect ~= nil) then\r\n                    CSAPI.SetGOActive(effect, false)\r\n                end\r\n            end, nil, hideTime)\r\n        end\r\n    elseif (isCan and not isUp) then\r\n        timer = timer - Time.deltaTime\r\n        if (timer <= 0) then\r\n            local decreaseAmount = Time.deltaTime / downTime\r\n            _height = _height - decreaseAmount * (len / 100)\r\n            isUp = false\r\n        end\r\n    end\r\nend\r\n\r\nfunction SetSoftMaskHeight()\r\n    -- local x, y = CSAPI.GetAnchor(softMask)\r\n    local y = img_fill.fillAmount\r\n    if (isUp) then\r\n        height = (y + lerpNum) >= _height and _height or (y + lerpNum)\r\n        height = height <= slider_max and height or slider_max\r\n        if (not isCan and height >= firstHeight) then\r\n            isCan = true\r\n        end\r\n    else\r\n        --height = (y - lerpNum) <= _height and _height or (y - lerpNum)\r\n        height = _height\r\n        height = height >= slider_min and height or slider_min\r\n    end\r\n    if (height >= slider_max or height <= slider_min) then\r\n        isOver = true\r\n    end\r\n    if (height >= _height) then\r\n        isUp = false\r\n    end\r\n    -- CSAPI.SetAnchor(softMask, -472.3, height, 0)\r\n    img_fill.fillAmount = height\r\nend\r\n\r\nfunction OnClickMask()\r\n    if (isOver == nil or not isCan) then\r\n        return\r\n    end\r\n    if (not isOver) then\r\n        if (clickIndex ~= nil and CardLive2DItem.IsIdle()) then\r\n            CardLive2DItem.PlayByIndex(clickIndex)\r\n        end\r\n        timer = holdTime\r\n        _height = _height + addNum * (len / 100)\r\n        isUp = true\r\n    end\r\nend\r\n",["__split_number"]="local this={}\nfunction this:SplitNumber(num)\r\n    local arr = {}\r\n    if num == 0 then\r\n        table.insert(arr, 0)\r\n        return arr\r\n    end\r\n    \r\n    -- 从低位往高位取\r\n    while num > 0 do\r\n        table.insert(arr, 1, num % 10)\r\n        num = math.floor(num / 10)\r\n    end\r\n    return arr\r\nend\r\n\r\nreturn this;\r\n"}
