-- Bounded Unity UI host for the unmodified miniature-game Lua scripts.
-- SPEC, SOURCES, ROWS are supplied from extracted resources by spine_ui.py.
Time={time=0,deltaTime=1/60}
function setUnscaledTime(t) Time.unscaledTime=t end
local serial=0
local roots, instances, callbacks, tasks, commands = {}, {}, {}, {}, {}
local idle=true
local multiTracks={}
function setMultiTracks(tracks) multiTracks=tracks or {} end
local spineTools={GetMulData=function(_,track)
 local value=multiTracks[tostring(track)]
 return value and {_progress=value.progress} or nil
end}
local remainder=0
local allNodes={}
-- Keep each Lua session's random state independent of the HTTP handler thread.
-- Windows xLua's math.random uses thread-local C state; consecutive requests
-- otherwise restart its sequence and repeatedly choose the minimum target count.
local randomState=1
local function nextRandom()
 -- Force floating-point arithmetic: Fengari's Lua integers are 32-bit.
 randomState=(randomState*1664525.0+1013904223.0)%4294967296.0
 return randomState/4294967296.0
end
local resetAnimated, syncActivity
local function copy(t)if type(t)~='table'then return t end;local o={};for k,v in pairs(t)do o[k]=copy(v)end;return o end
local function emit(c) commands[#commands+1]=c end
local function uid() serial=serial+1;return tostring(serial) end
local function detach(n)
 if not n.parent then return end
 for i,v in ipairs(n.parent.children) do if v==n then table.remove(n.parent.children,i);break end end
 n.parent=nil
end
local function parent(n,p)
 detach(n);n.parent=p;if p then p.children[#p.children+1]=n end
end
local function active(n)
 if not n.active or n.dead then return false end
 return not n.parent or active(n.parent)
end
local function animator(n)
 return {Play=function(_,name)
  if syncActivity then syncActivity()end
  if resetAnimated then resetAnimated(n)end
  n.anim=name;n.animAt=Time.time;n.transition=nil
  for _,id in ipairs(n.spec.animatorClips or {})do if SPEC.clips[id].name==name then n.clip=SPEC.clips[id];n.clipId=id;break end end
 end,SetTrigger=function(_,name) emit({type='camera',name=name,clip=SPEC.camera and SPEC.camera[name=='in' and 'Anim_zoomIn' or 'Anim_zoomOut']}) end}
end
local function newNode(d)
 local r=d.rect or {};local p=r.m_AnchoredPosition or {x=0,y=0}
 local n={id=uid(),name=d.name,active=d.active~=false,children={},spec=d,
  x=p.x,y=p.y,sx=(r.m_LocalScale or {x=1}).x,sy=(r.m_LocalScale or {y=1}).y,
  image=d.image,text=d.text,fillAmount=d.fill or 1,rect=copy(r),color=copy(d.color),alpha=d.alpha}
 allNodes[#allNodes+1]=n
 if d.defaultClip then n.clip=SPEC.clips[d.defaultClip];n.clipId=d.defaultClip;n.animAt=Time.time end
 n.gameObject=n
 n.transform=setmetatable({gameObject=n,SetAsLastSibling=function() local p=n.parent;parent(n,p) end,
  SetSiblingIndex=function(_,ix)local p=n.parent;if p then detach(n);n.parent=p;table.insert(p.children,math.min(ix+1,#p.children+1),n) end end,
  GetChild=function(_,ix)return n.children[ix+1].transform end},
  {__index=function(_,key)if key=='childCount' then return #n.children elseif key=='parent' then return n.parent and n.parent.transform end end})
 n.animator=animator(n)
 return n
end
ComUtil={GetCom=function(n,kind) return kind=='Animator' and n.animator or n end,
 GetLuaTable=function(n) return n.lua end}
CSAPI={
 -- Util.SetGOActive first tests Unity Object == null and returns.
 SetGOActive=function(n,on) if not n then return end
  n.active=on
  if syncActivity then syncActivity()end
 end,
 SetAnchor=function(n,x,y)n.x=x;n.y=y;n.localX=nil;n.localY=nil end,
 GetAnchor=function(n)return n.x,n.y,0 end,
 SetScale=function(n,x,y)n.sx=x;n.sy=y end,
 SetParent=function(n,p)parent(n,p)end,
 SetText=function(n,t)n.text=tostring(t)end,
 LoadImg=function(n,path,nativeSize,cb)
  local name=path:match('([^/]+)%.png$')
  local image=SPEC.images[name]
  assert(image,'unresolved UI Sprite: '..path)
  n.image=image
  local meta=SPEC.imageMetadata and SPEC.imageMetadata[image]
  if nativeSize~=false then
   assert(meta,'missing UI Sprite metadata: '..path)
   -- Image.SetNativeSize collapses the stretch anchors and uses sprite units.
   n.rect.m_AnchorMax=copy(n.rect.m_AnchorMin)
   local ppu=(meta.ppu or 100)/100
   n.rect.m_SizeDelta={x=meta.width/ppu,y=meta.height/ppu}
  end
  if cb then cb(n)end
 end,
 RandomInt=function(a,b)return a+math.floor(nextRandom()*(b-a+1))end,
 RandomFloat=function(a,b)return a+(b-a)*nextRandom()end,
 GetGlobalGO=function()return nil end,
 GetView=function()return nil end,
 PlayTempSound=function(name)emit({type='sound',name=name})end,
 PlayBGM=function(name)emit({type='bgm',name=name})end,
 StopBGM=function()emit({type='stop-bgm'})end,
