 local function clone(id)
  local d=SPEC.nodes[id];assert(d,'missing UI node '..id)
  local n=newNode(d);mapping[id]=n
  for _,child in ipairs(d.children or {})do parent(clone(child),n)end
  return n
 end
 local root=clone(assert(SPEC.templates[template],'missing UI template '..template))
 parent(root,p);if not p then roots[#roots+1]=root end
