 for _,n in pairs(mapping)do
  if n.spec.lua then
   local env=setmetatable({gameObject=n},{__index=_G});env.this=env;n.lua=env
   for _,b in pairs(mapping)do if b.spec.binding then env[b.spec.binding]=b end end
   assert(load(assert(SOURCES[n.spec.lua],'missing Lua '..n.spec.lua),n.spec.lua,'t',env))()
   instances[#instances+1]={node=n,env=env}
   for _,b in pairs(mapping)do if b.spec.click then b.handler=env end end
